310  static int GetVoiceAttributes(wchar_t *pw, int tag_type, SSML_STACK *ssml_sp, SSML_STACK *ssml_stack, int n_ssml_stack, char current_voice_id[40], espeak_VOICE *base_voice, char *base_voice_variant_name)
   311  {
   312          // Determines whether voice attribute are specified in this tag, and if so, whether this means
   313          // a voice change.
   314          // If it's a closing tag, delete the top frame of the stack and determine whether this implies
   315          // a voice change.
   316          // if there is a voice change, sets current_voice_id and returns CLAUSE_TYPE_VOICE_CHANGE
   317
   318          wchar_t *lang;
   319          wchar_t *gender;
   320          wchar_t *name;
   321          wchar_t *age;
   322          wchar_t *variant;
   323          int value;
   324          const char *new_voice_id;
   325
   326          static const MNEM_TAB mnem_gender[] = {
   327                  { "male", ENGENDER_MALE },
   328                  { "female", ENGENDER_FEMALE },
   329                  { "neutral", ENGENDER_NEUTRAL },
   330                  { NULL, ENGENDER_UNKNOWN }
   331          };
   332
   333          if (tag_type & SSML_CLOSE) {
   334                  // delete a stack frame
   335                  if (n_ssml_stack > 1)
   336                          n_ssml_stack--;
   337          } else {
   338                  // add a stack frame if any voice details are specified
   339                  lang = GetSsmlAttribute(pw, "xml:lang");
   340
   341                  if (tag_type != SSML_VOICE) {
   342                          // only expect an xml:lang attribute
   343                          name = NULL;
   344                          variant = NULL;
   345                          age = NULL;
   346                          gender = NULL;
   347                  } else {
   348                          name = GetSsmlAttribute(pw, "name");
   349                          variant = GetSsmlAttribute(pw, "variant");
   350                          age = GetSsmlAttribute(pw, "age");
   351                          gender = GetSsmlAttribute(pw, "gender");
   352                  }
   353
   354                  if ((tag_type != SSML_VOICE) && (lang == NULL))
   355                          return 0; // <s> or <p> without language spec, nothing to do
   356
   357                  ssml_sp = &ssml_stack[n_ssml_stack++];
   358
   359                  attrcopy_utf8(ssml_sp->language, lang, sizeof(ssml_sp->language));
   360                  attrcopy_utf8(ssml_sp->voice_name, name, sizeof(ssml_sp->voice_name));
   361                  if ((value = attrnumber(variant, 1, 0)) > 0)
   362                          value--; // variant='0' and variant='1' the same
   363                  ssml_sp->voice_variant_number = value;
   364                  ssml_sp->voice_age = attrnumber(age, 0, 0);
   365                  ssml_sp->voice_gender = attrlookup(gender, mnem_gender);
   366                  ssml_sp->tag_type = tag_type;
   367          }
   368
   369          new_voice_id = VoiceFromStack(ssml_stack, n_ssml_stack, base_voice, base_voice_variant_name);
   370          if (strcmp(new_voice_id, current_voice_id) != 0) {
   371                  // add an embedded command to change the voice
   372                  strcpy(current_voice_id, new_voice_id);
   373                  return CLAUSE_TYPE_VOICE_CHANGE;
   374          }
   375
   376          return 0;
   377  }
